// Draft 20.6: one manager PIN per company, entered on demand. Never persist PIN in localStorage.
const palManagerPins={};
function palPinCompany(url){const m=String(url).match(/^\/api\/(baa|newstart)\//);return m?(m[1]==='baa'?'born-again-air':'newstart'):null;}
function palProtectedUrl(url,options){const u=String(url),method=String(options?.method||'GET').toUpperCase();return (method==='POST'&&/^\/api\/(baa|newstart)\/documents\/delete(?:\?|$)/.test(u))||/^\/api\/(baa|newstart)\/(permanent(?:\/|$)|vendors(?:\/|$)|accounting(?:\/|$)|reports(?:\/|$)|documents\/move-permanent(?:\/|$))/.test(u)||(method==='POST'&&/^\/api\/(baa|newstart)\/documents\?collection=permanent(?:&|$)/.test(u));}
const palOriginalFetch=window.fetch.bind(window);
window.fetch=async function(url,options={}){
 if(!palProtectedUrl(url,options))return palOriginalFetch(url,options);
 const company=palPinCompany(url);
 if(!palManagerPins[company]){
  const entered=window.prompt('Enter manager PIN for '+(company==='born-again-air'?'Born Again Air':'Newstart'));
  if(entered===null)throw new Error('Manager PIN entry cancelled');
  palManagerPins[company]=entered;
 }
 const send=()=>palOriginalFetch(url,{...options,headers:{...(options.headers||{}),'x-pal-manager-pin':palManagerPins[company]}});
 let response=await send();
 if(response.status===403){
  const data=await response.clone().json().catch(()=>({}));
  if(data.code==='MANAGER_PIN_REQUIRED'){
   delete palManagerPins[company];
   const entered=window.prompt('Incorrect manager PIN. Enter PIN again:');
   if(entered===null)throw new Error('Manager PIN entry cancelled');
   palManagerPins[company]=entered;response=await send();
  }
 }
 return response;
};
