 async function reload(){try{const r=await fetch(`/api/${company==='newstart'?'newstart':'baa'}/${activeCollection==='permanent'?'permanent':'documents'}`);const d=await r.json();if(!r.ok)throw Error(d.error||'Could not load documents');if(!d.configured){list.innerHTML='<p class="doc-muted">Secure storage has not been configured yet. PAL will connect the private Supabase bucket.</p>';return;}list.innerHTML=d.files.length?d.files.map(f=>`<div class="doc-item"><div class="doc-file-icon">${esc(f.displayName.split('.').pop().toUpperCase())}</div><div class="doc-file-detail"><strong>${esc(f.displayName)}</strong><small>${esc(f.created_at||'Time unavailable')} · ${Math.ceil(f.size/1024)} KB</small><small class="doc-status">${esc(({uploaded:'Uploaded',needs_review:'Needs Review',approved:'Approved',entered_qbo:'Entered in QuickBooks',attachment_verified:'Attachment Verified',permanent:'Permanent'})[f.status?.processing_status]||'Uploaded')}${f.status?.hold?' · On Hold':''}</small>${activeCollection==='accounting'&&f.status?.processing_status==='needs_review'?'<small class="doc-status">Possible permanent record — manager review required</small>':''}</div><button type="button" class="doc-secondary doc-download" data-name="${esc(f.name)}">Download</button>${activeCollection==='accounting'&&(state.owner||state.membership.role==='manager')&&f.status?.processing_status==='needs_review'?`<button type="button" class="doc-secondary" data-move="${esc(f.name)}">Copy to Permanent</button>`:''}${(state.owner||state.membership.role==='manager')?`<button type="button" class="doc-trash" data-name="${esc(f.name)}" aria-label="Remove ${esc(f.displayName)}" title="${activeCollection==='permanent'?'Remove permanent record (archived)':'Delete document'}">🗑</button>`:''}</div>`).join(''):'<p class="doc-muted">No documents yet. Upload your first batch above.</p>' ;list.querySelectorAll('.doc-download').forEach(b=>b.onclick=()=>download(b.dataset.name));list.querySelectorAll('[data-move]').forEach(b=>b.onclick=async()=>{if(!confirm('Copy this document into Permanent Records and retain the original on hold?'))return;b.disabled=true;try{const r=await fetch(`/api/${company==='newstart'?'newstart':'baa'}/documents/move-permanent`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:b.dataset.move})});const d=await r.json();if(!r.ok)throw Error(d.error||'Copy failed');msg.textContent=d.message;await reload();}catch(e){msg.textContent=e.message;b.disabled=false;}});list.querySelectorAll('.doc-trash').forEach(b=>b.onclick=async()=>{if(!confirm(activeCollection==='permanent'?'Remove this Permanent Record from the active list? A private recovery copy will be saved. Upload the new contract separately if replacing it.':'Permanently delete this document? This cannot be undone.'))return;b.disabled=true;try{const r=await fetch(`/api/${company==='newstart'?'newstart':'baa'}/${activeCollection==='permanent'?'permanent/delete':'documents/delete'}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(activeCollection==='permanent'?{name:b.dataset.name,confirm:true}:{names:[b.dataset.name]})});const d=await r.json();if(!r.ok)throw Error(d.error||'Delete failed');msg.textContent=activeCollection==='permanent'?'Permanent Record removed; private recovery copy retained.':'Document deleted.';await reload();}catch(e){msg.textContent=e.message;b.disabled=false;}});}catch(e){list.textContent=e.message;}}
 async function download(name){const r=await fetch(`/api/${company==='newstart'?'newstart':'baa'}/${activeCollection==='permanent'?'permanent':'documents'}/link`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});const d=await r.json();if(!r.ok)throw Error(d.error||'Download failed');const a=document.createElement('a');a.href=d.url;a.target='_blank';a.rel='noopener noreferrer';document.body.append(a);a.click();a.remove();}
