function newstart(){shell(`<main class="dashboard baa-main"><div class="dash-heading"><div><div class="eyebrow dark-eye">PAL / NEWSTART</div><h1>Newstart workspace</h1><p>Property operations, documents and accounting preparation.</p></div><span class="secure-pill">Private company workspace</span></div><div class="baa-tabs newstart-tabs"><button data-newstart-section="documents" type="button">Document Uploads</button><button data-newstart-section="reports" type="button">Reports</button></div><div id="newstart-document-content" class="baa-work baa-home"><div class="baa-landing"><p>Select a section above to get started.</p></div></div><div class="newstart-persistent-logo"><img class="newstart-brand-image" src="/newstart-logo.png" alt="Newstart, inc."></div>${state.owner?'<p><a href="/owner">← Return to owner dashboard</a></p>':''}</main>`);document.querySelectorAll('[data-newstart-section]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-newstart-section]').forEach(x=>x.classList.toggle('selected',x===b));const el=document.getElementById('newstart-document-content');el.classList.remove('baa-home');if(b.dataset.newstartSection==='documents')baaDocuments(el,'newstart');else if(b.dataset.newstartSection==='reports')el.innerHTML='<h2>Reports</h2><p>Newstart reporting will be available after the reporting automation is connected.</p>';else el.innerHTML='<h2>Property Operations</h2><p>Time tracking, work orders, materials and payroll preparation are planned for the Newstart build.</p>';});}
function forbidden(){shell(`<main class="simple-notice"><div class="empty-icon">⛨</div><h1>Private owner area</h1><p>This account does not have permission to access the PAL owner dashboard.</p><a href="/app" class="btn btn-primary">Go to your workspace ↗</a></main>`);}
function clerkDomain(){const encoded=state.publishableKey.split('_')[2];if(!encoded)throw new Error('Missing Clerk publishable key');return atob(encoded).replace(/\$$/,'');}
let clerkPromise;
async function initializeClerk(kind){const err=document.getElementById('auth-error');try{if(!clerkPromise){clerkPromise=(async()=>{const domain=clerkDomain();await loadScript(`https://${domain}/npm/@clerk/ui@1/dist/ui.browser.js`);await loadScript(`https://${domain}/npm/@clerk/clerk-js@6/dist/clerk.browser.js`,{'data-clerk-publishable-key':state.publishableKey});if(!window.Clerk)throw new Error('Clerk did not initialize');await window.Clerk.load({ui:{ClerkUI:window.__internal_ClerkUICtor}});})();}await clerkPromise;const button=document.getElementById('user-button');if(button&&window.Clerk.isSignedIn)window.Clerk.mountUserButton(button,{afterSignOutUrl:'/'});if(kind==='user')return;if(window.Clerk.isSignedIn){location.replace(state.owner?'/owner':'/app');return;}const mount=document.getElementById('clerk-mount');mount.innerHTML='';const options={routing:'hash',signInUrl:'/login',signUpUrl:'/register',fallbackRedirectUrl:'/app',signInFallbackRedirectUrl:'/app',signUpFallbackRedirectUrl:'/app'};if(kind==='login')window.Clerk.mountSignIn(mount,options);else window.Clerk.mountSignUp(mount,options);}catch(e){if(err)err.textContent='Unable to load secure login. Check your Clerk settings and refresh. '+e.message;const mount=document.getElementById('clerk-mount');if(mount)mount.innerHTML='';console.error('PAL Clerk:',e);}}
function loadScript(src,attributes={}){return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.crossOrigin='anonymous';script.async=true;for(const [key,val] of Object.entries(attributes))script.setAttribute(key,val);script.onload=resolve;script.onerror=()=>reject(new Error('Cannot load '+src));document.head.appendChild(script);});}
if(state.view==='home')home();else if(state.view==='login'||state.view==='register')authPage(state.view);else if(state.view==='owner')owner();else if(state.view==='customer')customer();else if(state.view==='baa')baa();else if(state.view==='newstart')newstart();else forbidden();

async function baaViewData(kind,q='',offset=0,sheet='current'){
 const host=document.getElementById('baa-data-view');if(!host)return;
 host.innerHTML='<p>Loading records…</p>';
 try{
  const d=await api('/'+kind+'?q='+encodeURIComponent(q)+'&offset='+offset+'&sheet='+encodeURIComponent(sheet));
  const catalog=kind==='catalog';
  host.innerHTML=`<div class="baa-card"><h3>${catalog?'Part / Core Database':'Price List '+(sheet==='current'?'Current':sheet.toUpperCase())} (${d.count} matching)</h3><form id="baa-filter"><input name="q" placeholder="Search part or core number" value="${esc(q)}"><button>Search</button></form><div class="baa-tablewrap"><table class="baa-table"><thead><tr>${catalog?'<th>Part Number</th><th>Core Number</th>':'<th>BASE PN (Part)</th><th>CORE BASE (Core)</th><th>Price</th>'}</tr></thead><tbody>${d.rows.map(x=>`<tr><td>${esc(catalog?x.part:x.basePart)}</td><td>${esc(catalog?x.core:x.coreBase)}</td>${catalog?'':`<td>$${Number(x.price).toFixed(2)}</td>`}</tr>`).join('')}</tbody></table></div><div class="baa-actions"><button id="baa-prev" ${offset===0?'disabled':''}>Previous</button><span>Showing ${d.rows.length?offset+1:0}–${offset+d.rows.length} of ${d.count}</span><button id="baa-next" ${offset+100>=d.count?'disabled':''}>Next</button></div></div>`;
  host.querySelector('#baa-filter').onsubmit=e=>{e.preventDefault();baaViewData(kind,new FormData(e.target).get('q'),0,sheet);};
  host.querySelector('#baa-prev').onclick=()=>baaViewData(kind,q,Math.max(0,offset-100),sheet);
  host.querySelector('#baa-next').onclick=()=>baaViewData(kind,q,offset+100,sheet);
 }catch(e){host.innerHTML='<p class="baa-warning">'+esc(e.message)+'</p>';}
}

// Phase 1 private automation monitoring. Customer pages and warehouse functions untouched.
async function automationCenter(el){
 el.innerHTML=`<div class="section-top"><div><div class="eyebrow dark-eye">PAL / OWNER ONLY</div><h2>Automation Center</h2><p>Phase 1: infrastructure status. No AI jobs, accounting changes, cleanup deletions or emails are executed by this screen.</p></div></div><div class="detail-panel"><label for="pal-auto-tenant">Company</label> <select id="pal-auto-tenant"><option value="born-again-air">Born Again Air</option><option value="newstart">Newstart</option></select><div id="pal-auto-status" class="muted">Loading…</div><div id="pal-auto-jobs"></div></div>`;
 const tenant=el.querySelector('#pal-auto-tenant');tenant.onchange=refresh;
 async function refresh(){const status=el.querySelector('#pal-auto-status'),jobs=el.querySelector('#pal-auto-jobs');status.textContent='Checking secure automation database…';jobs.innerHTML='';try{
  const r=await fetch('/api/owner/automation/status?tenant='+encodeURIComponent(tenant.value));const data=await r.json();if(!r.ok)throw Error(data.error||'Unavailable');
  status.innerHTML=`<p><strong>Automation:</strong> ${data.enabled?'Enabled (queue only)':'Paused'} &nbsp; <strong>xAI key:</strong> ${data.xaiConfigured?'Configured':'Not configured'} &nbsp; <strong>Database:</strong> ${data.databaseConfigured?'Configured':'Not configured'}</p><p><strong>Seven roles:</strong> ${data.roles.map(esc).join(', ')}</p><button id="pal-auto-toggle" type="button">${data.enabled?'Pause automation':'Enable scheduling (no bot execution)'}</button>`;
  status.querySelector('#pal-auto-toggle').onclick=async()=>{if(!confirm('Change scheduling state for '+tenant.value+'? Phase 1 only queues jobs; it does not execute bots.'))return;const result=await fetch('/api/owner/automation/enabled',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tenant:tenant.value,enabled:!data.enabled})});if(!result.ok){alert('Could not change state');return;}refresh();};
  jobs.innerHTML='<h3>Recent jobs</h3>'+(data.jobs.length?data.jobs.map(j=>`<p><strong>${esc(j.role)}</strong> — ${esc(j.status)} — ${esc(j.job_key)}</p>`).join(''):'<p>No jobs recorded.</p>');
 }catch(e){status.textContent=e.message;}}
 refresh();
}
